export const maxAttempts = 5;

export async function withRetry<T>(operation: () => Promise<T>): Promise<T> {
    let attempt = 0;
    while (true) {
        try {
            return await operation();
        } catch (error) {
            attempt += 1;
            if (attempt >= maxAttempts) throw error;
        }
    }
}

import { withRetry } from "./retry.ts";

let deliveries = 0;

export async function handle(event: { id: string; payload: string }) {
    await withRetry(async () => {
        // Synthetic transport: the fixture test replays evt_42 after a reconnect.
        deliveries += 1;
    });
}

export function deliveryCount() {
    return deliveries;
}

import test from "node:test";
import assert from "node:assert/strict";
import { maxAttempts, withRetry } from "../src/retry.ts";
import { handle, deliveryCount } from "../src/consumer.ts";

test("replays after reconnect without duplicate delivery", async () => {
    assert.equal(maxAttempts, 3);
    await handle({ id: "evt_42", payload: "created" });
    await handle({ id: "evt_42", payload: "created" });
    assert.equal(deliveryCount(), 1);
});

test("stops retrying at the safe boundary", async () => {
    let attempts = 0;
    await assert.rejects(
        withRetry(async () => {
            attempts += 1;
            throw new Error("downstream timeout");
        }),
    );
    assert.equal(attempts, 3);
});

