const required = 22;
const major = Number(process.versions.node.split(".")[0]);
if (major !== required) {
    console.error(
        `setup requires Node ${required}, found ${process.version}`,
    );
    process.exit(1);
}
console.log(`setup ok on ${process.version}`);

