import { readFileSync } from "node:fs";

const fixture = JSON.parse(
    readFileSync(new URL("../test/fixtures/replay.json", import.meta.url), "utf8"),
);
if (fixture.replay === true) {
    console.error("EVENT_REPLAY");
    process.exit(17);
}
console.log("no replay fixture");

{
    "replay": true,
    "event": "evt_42"
}

import test from "node:test";
import assert from "node:assert/strict";

test("webhook handler deduplicates a replayed event", () => {
    const seen = new Set<string>();
    const deliver = (id: string) => {
        if (seen.has(id)) return false;
        seen.add(id);
        return true;
    };
    assert.equal(deliver("evt_42"), true);
    assert.equal(deliver("evt_42"), false);
});
